import{_ as t,l as r,o,c as s,v as i,p as l,x as n,d as E,i as d,S as M}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"MiniMax M-2.5","description":"","frontmatter":{"title":"MiniMax M-2.5","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/minimax-m-2-5.md","filePath":"llm/minimax-m-2-5.md","lastUpdated":1789023840000}'),g={name:"llm/minimax-m-2-5.md"};function m(h,a,p,B,P,c){const e=r("Mermaid");return o(),s("div",null,[a[1]||(a[1]=i('<h1 id="minimax-m-2-5" tabindex="-1">MiniMax M-2.5 <a class="header-anchor" href="#minimax-m-2-5" aria-label="Permalink to &quot;MiniMax M-2.5&quot;">​</a></h1><div class="epigraph"><p>在数十万真实环境里做强化学习之后，M2.5 把编码、工具搜索与办公交付当成同一套经济任务；100 token/s 连续跑一小时大约 1 美元，用来把智能体账单从「先问价」里拿掉。</p><footer>—— MiniMax，MiniMax M2.5: Built for Real-World Productivity，2026-02-12</footer></div><p><a href="/llm/minimax-m1">MiniMax-M1</a> 用混合注意力与 CISPO 证明长思维 RL 可训。M2 系列把主轴换成<strong>高稀疏 MoE 上的智能体</strong>。2026 年 2 月 12 日的 <strong>MiniMax-M2.5</strong> 是该系列在约三个半月内的第三颗：官方新闻强调 SWE-Bench Verified <strong>80.2%</strong>、Multi-SWE-Bench <strong>51.3%</strong>、带上下文管理的 BrowseComp <strong>76.3%</strong>，以及相对 M2.1 在 SWE 评测上 <strong>37%</strong> 的端到端加速。价格叙事是「智能便宜到不必计量」：Lightning 档约 100 TPS、每百万输入 0.30 / 输出 2.40 美元；标准档约 50 TPS、价减半。本篇以这篇新闻为主；系列骨干规格见 M2 技术报告（社区引用 arXiv:2605.26494 的约 <strong>229.9B / 9.8B 激活</strong>），M2.5 正文没有重开层表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>M1 解决的是长生成在混合核上的 FLOPs；到 2026 年初，用户要的是能当同事：修多语言仓库、在陌生脚手架里调工具、交出可送审的 Word / PPT / Excel，而且墙钟要对齐截止日期。只加 SWE 分数会训练出会刷基准、不会做 0-to-1 系统设计的模型。M2.5 把问题收成：在<strong>同一套激活很小的 MoE</strong> 上，用大规模真实环境 RL 把架构师式规划、搜索轮次效率、办公交付同时拉起来，并把服务做成 50/100 TPS 两档同能力。</p><p>第二个问题是泛化。官方特意在 Droid 与 OpenCode 上测 SWE-Bench Verified（79.7 / 76.1），对标 Opus 4.6，用来证明不是只拟合 Claude Code 一种 harness。</p><h3 id="同能力两档-lightning-与-standard" tabindex="-1">同能力两档：Lightning 与 Standard <a class="header-anchor" href="#同能力两档-lightning-与-standard" aria-label="Permalink to &quot;同能力两档：Lightning 与 Standard&quot;">​</a></h3><p>新闻写 M2.5 与 M2.5-Lightning <strong>能力相同、速度与价格不同</strong>。Lightning 约 100 TPS，标准约 50 TPS；二者都支持缓存。按输出价，官方称约为当时 Opus / Gemini 3 Pro / GPT-5 的十分之一到二十分之一。100 TPS 连续一小时约 <strong>1 美元</strong>，50 TPS 约 <strong>0.30 美元</strong>。这是产品算术，不是架构分支——不要把 Lightning 写成更小 MoE。</p><p><span class="marginnote">SWE-Bench Verified 官方脚手架写明：内部基建、Claude Code、覆盖默认系统提示、四次平均。Droid / OpenCode 用默认提示。换 harness 则 80.2% 不可比。每任务平均约 3.52M token，相对 M2.1 的 3.72M；墙钟从 31.3 分钟到 22.8 分钟。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编码：RL 覆盖十余种语言（Go、C/C++、TS、Rust、Kotlin、Python、Java、JS、PHP、Lua、Dart、Ruby 等）与 <strong>超过 20 万</strong>真实环境，范围从 0-to-1 设计、环境搭建、1-to-10 开发、到 90-to-100 的评审测试，平台含 Web / Android / iOS / Windows 与后端 API、库表，而不只是前端 demo。训练中冒出 <strong>先写 spec 再写代码</strong> 的架构师倾向。内部把 VIBE 升级为更难的 VIBE-Pro。搜索与工具：BrowseComp、WideSearch，以及自建 <strong>RISE</strong>（专家级真实检索题，Playwright 浏览器套件）。相对 M2.1，多任务上大约 <strong>少 20% 轮次</strong> 打出更高分——路径更短，不是更长的思维链自我欣赏。</p><p>办公：与金融、法律、社科从业者共建需求与数据。内部 <strong>GDPval-MM</strong> 对交付物质量与轨迹专业性做成对比较，并盯全程 token 成本；官方称平均胜率 <strong>59.0%</strong>。另有 MEWC（Excel 竞赛题）与金融建模内部集。</p>',12)),(o(),l(M,null,{default:n(()=>[d(e,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENV%5B%2220%20%E4%B8%87%2B%20%E7%9C%9F%E5%AE%9E%E7%8E%AF%E5%A2%83%22%5D%20--%3E%20FORGE%5B%22Forge%EF%BC%9A%E6%99%BA%E8%83%BD%E4%BD%93%E4%B8%8E%E8%AE%AD%E7%BB%83%E5%BC%95%E6%93%8E%E8%A7%A3%E8%80%A6%22%5D%0A%20%20FORGE%20--%3E%20CISPO%5B%22CISPO%EF%BC%9AMoE%20%E5%A4%A7%E8%A7%84%E6%A8%A1%20RL%20%E7%A8%B3%E5%AE%9A%22%5D%0A%20%20CISPO%20--%3E%20PR%5B%22%E8%BF%87%E7%A8%8B%E5%A5%96%E5%8A%B1%20%2B%20%E8%BD%A8%E8%BF%B9%E8%80%97%E6%97%B6%22%5D%0A%20%20PR%20--%3E%20M25%5B%22M2.5%20%2F%20Lightning%20%E5%90%8C%E6%9D%83%E4%B8%8D%E5%90%8C%E9%80%9F%22%5D%0A%20%20M25%20--%3E%20CODE%5B%22%E7%BC%96%E7%A0%81%E5%85%A8%E7%94%9F%E5%91%BD%E5%91%A8%E6%9C%9F%22%5D%0A%20%20M25%20--%3E%20SRCH%5B%22%E6%90%9C%E7%B4%A2%20%2F%20%E5%B7%A5%E5%85%B7%E5%B0%91%E8%BD%AE%E6%AC%A1%22%5D%0A%20%20M25%20--%3E%20OFF%5B%22Word%20PPT%20Excel%20%E5%8F%AF%E4%BA%A4%E4%BB%98%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h3 id="forge、cispo-与过程奖励" tabindex="-1">Forge、CISPO 与过程奖励 <a class="header-anchor" href="#forge、cispo-与过程奖励" aria-label="Permalink to &quot;Forge、CISPO 与过程奖励&quot;">​</a></h3><p><strong>Forge</strong> 是自研 agent-native RL 框架：中间层把训练–推理引擎与智能体解耦，任意 agent 可接入，用来优化跨脚手架泛化。异步调度在吞吐与 off-policy 程度之间折中；训练样本的树结构合并宣称约 <strong>40×</strong> 训练加速。算法上继续用他们提出的 <strong>CISPO</strong> 稳住 MoE（见 <a href="/llm/minimax-m1">M1</a> 对重要性权重裁剪的讨论）。长上下文 rollout 的信用分配用<strong>过程奖励</strong>盯生成质量；并用轨迹耗时对齐「既要聪明又要快」。更完整的 RL 缩放说明，新闻答应另文展开——本篇不编那篇未引用论文的公式。</p><p><span class="marginnote">M2 系列骨干在技术报告里写为约 62 层、229.9B 总量、9.8B 激活、256 专家 sigmoid 门 top-8。M2.5 新闻以 RL 与产品为主；把该表当作系列默认可以，但应标明出处是系列报告而非 M2.5 新闻正文。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>9.8B 量级激活决定单 token FLOPs，使 100 TPS 的价能落在每小时 1 美元附近；229B 总量决定专家容量与装载。CISPO 不把低概率反思 token 在第一次更新后裁死，长程智能体才还能改主意。过程奖励对抗「轨迹又长又错仍拿结局分」。把完成时间写进奖励，模型才会学并行工具调用——SWE 墙钟降 37% 的直接来源之一。</p><p>Office Skills 在 MiniMax Agent 的 MAX 模式里按文件类型加载，再与行业 SOP 拼成可复用 Expert（官方称用户已建超 1 万）。这是产品层的程序化技能，不是 MoE 里多出来的「Excel 专家」。公司内部宣称约 30% 任务由 M2.5 自主完成、新提交代码约 80% 由模型生成——这是部署统计，不是基准。</p><h3 id="和改进速率" tabindex="-1">和改进速率 <a class="header-anchor" href="#和改进速率" aria-label="Permalink to &quot;和改进速率&quot;">​</a></h3><p>从 10 月末到 2 月，M2 → M2.1 → M2.5，官方用 SWE-Bench Verified 的斜率对比 Claude / GPT / Gemini 家族。机制解释是 RL 环境数量（「公司里大多数任务都做成了环境」）与 Forge 吞吐，而不是换注意力公式。M1 的 Lightning Attention 混合核与 M2 的全注意力 MoE 不是同一对象；不要把 M1 的 1M 窗口默认抄到 M2.5——NVIDIA 模型卡一类第三方页写过约 196K 上下文，<strong>以 MiniMax 当时模型卡为准</strong>。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>新闻里大量分数来自内部集（VIBE-Pro、RISE、GDPval-MM、金融建模）。内部集有设计者偏差；对外引用应优先 SWE / BrowseComp 并抄脚手架脚注。Terminal Bench 2 改了部分 Dockerfile、统一超时与空响应重试，与别人的 2.0 表不可直接比。BrowseComp 在用量超窗口 30% 时丢弃全部历史，管理策略是分数的一部分。权重开源与否、MIT 还是 Modified-MIT，以仓库 LICENSE 为准（M2.5 常见 MIT / modified-mit 表述，后续 M2.7 许可更紧）。</p><p>不要把「1 美元/小时」理解成含工具、搜索与缓存未命中的全包价。不要编 M2.5 独有的层宽。后续 M2.7 是另一检查点。</p><p><span class="marginnote">出处：MiniMax，<em>MiniMax M2.5: Built for Real-World Productivity</em>（2026-02-12）。系列结构见表述于 M2 技术报告时再引用 arXiv:2605.26494。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>M2.5（2026-02-12）是 M2 系智能体旗舰：编码 / 搜索 / 办公，SWE-Verified 80.2%，BrowseComp（带管理）76.3%。</li><li>Lightning 与 Standard 同能力不同 TPS 与价；100 TPS 连续一小时约 1 美元。</li><li>Forge + CISPO + 过程奖励 + 耗时对齐，是公开的 RL 方法句；层表在系列报告而非本则新闻。</li><li>评测必须写 harness、是否改题面、上下文丢弃策略。</li><li>出处：minimax.io 新闻；骨干规格引用系列报告。</li></ul>',14))])}const C=t(g,[["render",m]]);export{S as __pageData,C as default};
